begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(26);
insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at,confirmation_token,email_change,email_change_token_new,recovery_token) values
('00000000-0000-0000-0000-000000000000','44444444-4444-4444-8444-444444444444','authenticated','authenticated','business@example.test',crypt('password',gen_salt('bf')),now(),'{}','{"username":"BusinessTester"}',now(),now(),'','','',''),
('00000000-0000-0000-0000-000000000000','55555555-5555-4555-8555-555555555555','authenticated','authenticated','other-business@example.test',crypt('password',gen_salt('bf')),now(),'{}','{"username":"OtherBusiness"}',now(),now(),'','','','');
select has_table('public','business_productions','production table exists');
select has_table('public','production_output_reservations','output reservations exist');
select has_table('public','business_tax_totals','business tax sink exists');
select has_function('public','open_business',array['text','uuid'],'open business RPC exists');
select has_function('public','start_business_production',array['uuid','text','uuid'],'start RPC exists');
select has_function('public','claim_business_production',array['uuid','uuid'],'claim RPC exists');
select is((select founder_points from public.quests where id='daily-business-1'),10,'business quest reward is 10 FP');
select is((select business_slots from public.properties where player_id='44444444-4444-4444-8444-444444444444'),0,'starter has no slot');
set local role authenticated; select set_config('request.jwt.claim.sub','44444444-4444-4444-8444-444444444444',true);
select throws_like($$select public.open_business('restaurant','40000000-0000-4000-8000-000000000001')$$,'%No business slot%','cannot open without slot');
select throws_like($$select public.open_business('bank','40000000-0000-4000-8000-000000000002')$$,'%Unsupported%','unsupported business fails');
reset role; update public.properties set level=2,storage_capacity=100,resident_capacity=3,business_slots=1 where player_id='44444444-4444-4444-8444-444444444444'; update public.player_economy set coins=2000 where player_id='44444444-4444-4444-8444-444444444444'; update public.player_resources set amount=10 where player_id='44444444-4444-4444-8444-444444444444' and resource in('food','wood','iron');
set local role authenticated; select set_config('request.jwt.claim.sub','44444444-4444-4444-8444-444444444444',true);
select lives_ok($$select public.open_business('restaurant','40000000-0000-4000-8000-000000000003')$$,'opens Restaurant');
select is((select coins from public.player_economy where player_id=auth.uid()),1300::bigint,'opening deducts authoritative 700 Coins');
select throws_like($$select public.open_business('general_store','40000000-0000-4000-8000-000000000004')$$,'%No business slot%','slot limit is enforced');
select is((select count(*) from public.economy_transactions where player_id=auth.uid() and transaction_type='BUSINESS_OPEN_COST'),1::bigint,'opening ledger is written once');
select lives_ok(format('select public.assign_resident_to_business(%L,%L,%L)',(select id from public.residents where player_id=auth.uid()),(select id from public.player_businesses where player_id=auth.uid()),'40000000-0000-4000-8000-000000000005'),'resident assignment succeeds');
select is((select work_state from public.residents where player_id=auth.uid()),'ASSIGNED_BUSINESS','assignment updates authoritative work state');
select lives_ok(format('select public.start_business_production(%L,%L,%L)',(select id from public.player_businesses where player_id=auth.uid()),'restaurant_meals','40000000-0000-4000-8000-000000000006'),'production starts');
select is((select amount from public.player_resources where player_id=auth.uid() and resource='food'),6,'inputs consumed at start');
select is(public.production_reserved_storage(auth.uid()),2,'two output units reserved');
select is((select work_state from public.residents where player_id=auth.uid()),'PRODUCING','resident enters PRODUCING');
select throws_like(format('select public.claim_business_production(%L,%L)',(select id from public.business_productions where player_id=auth.uid()),'40000000-0000-4000-8000-000000000007'),'%PRODUCTION_NOT_READY%','early claim rejected');
select throws_like($$select public.execute_job('farmer','40000000-0000-4000-8000-000000000008')$$,'%RESIDENT_PRODUCING%','job blocked while producing');
reset role; update public.business_productions set ready_at=now()-interval '1 second' where player_id='44444444-4444-4444-8444-444444444444';
set local role authenticated; select set_config('request.jwt.claim.sub','44444444-4444-4444-8444-444444444444',true);
select lives_ok(format('select public.claim_business_production(%L,%L)',(select id from public.business_productions where player_id=auth.uid()),'40000000-0000-4000-8000-000000000009'),'ready production claims');
select is((select amount from public.player_resources where player_id=auth.uid() and resource='meals'),2,'claim converts reservation to Meals once');
select is(public.production_reserved_storage(auth.uid()),0,'reservation released at claim');
select is((select xp from public.player_skills where player_id=auth.uid() and skill='chef'),12,'Chef XP awarded once');
select * from finish(); rollback;
